.dx-state-disabled.dx-widget {
    opacity: .5;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
    cursor: default;
}

    .dx-state-disabled .dx-widget .dx-widget,
    .dx-state-disabled.dx-widget .dx-widget {
        opacity: 1;
