.dx-card {
    overflow: hidden;
    border: 1px solid #ddd;
    border-radius: 4px;
    background-color: #fff;
}

.dx-field input,
.dx-field textarea {
    font-family: 'Helvetica Neue','Segoe UI',Helvetica,Verdana,sans-serif;
