    float: left;
    width: 40%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: #333;
    cursor: default;
    padding: 8px 15px 9px 0;
}

.dx-field-value.dx-attention {
    color: #d9534f;
    padding: 8px 10px 9px 28px;
    position: relative;
}

