.fade-slide-up {
    animation: fadeSlideUp 0.45s ease-out forwards;
}

@keyframes fadeSlideUp {
    0% {
        opacity: 0;
    }

    100% {
        opacity: 1;
    }
}
.expand-ltr {
    transform-origin: left center;
    animation: expandLTR 220ms ease-out forwards;
}

.expand-rtl {
    transform-origin: right center;
    animation: expandRTL 220ms ease-out forwards;
}

.collapse-rtl {
    transform-origin: right center;
    animation: collapseRTL 220ms ease-in forwards;
}

@keyframes expandLTR {
    from {
        opacity: 0;
        transform: scaleX(0);
    }

    to {
        opacity: 1;
        transform: scaleX(1);
    }
}

@keyframes expandRTL {
    from {
        opacity: 0;
        transform: scaleX(0);
    }

    to {
        opacity: 1;
        transform: scaleX(1);
    }
}


@keyframes collapseRTL {
    from {
        opacity: 1;
        transform: scaleX(1);
    }

    to {
        opacity: 0;
        transform: scaleX(0);
    }
}

.tab-container {
    animation: fadeSlideUp 0.45s ease-out forwards;
