/* Dot */
.notification-dot {
    transform: scale(1);
    transform-origin: center;
    transition: transform 0.3s ease;
}

.notification-icon.has-notification .notification-dot {
    transform: scale(1.3);
    animation: pulse 1.5s infinite ease-in-out;
}

/* Pulse effect */
@keyframes pulse {
    0% {
        transform: scale(1.3);
    }

    50% {
        transform: scale(1.5);
    }

    100% {
        transform: scale(1.3);
    }
}
