.attachment-drop-zone {
    width: 100%;
    min-height: 92px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    box-sizing: border-box;
    background: linear-gradient(135deg, var(--form-attachment-surface, #f5faff), var(--form-attachment-icon-bg, #ffffff));
    border: 1.5px dashed var(--form-attachment-border, #c7daf5);
    border-radius: 12px;
    padding: 16px 20px;
    text-align: center;
    cursor: pointer;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .7), 0 3px 11px rgba(31, 42, 55, .04);
    transition: background .18s ease, border-color .18s ease, box-shadow .18s ease, transform .18s ease;
}

.attachment-drop-zone:hover,
.attachment-drop-zone:focus-visible {
    background: var(--form-attachment-hover-surface, #edf5ff);
    border-color: var(--form-attachment-accent, #5d95f5);
    box-shadow: 0 0 0 3px var(--form-node-focus-ring, rgba(93, 149, 245, .14)), 0 7px 18px rgba(31, 42, 55, .06);
}

.attachment-drop-zone:focus-visible {
    outline: none;
}

.attachment-drop-zone.is-dragging {
    min-height: 128px;
    border-color: var(--form-attachment-accent, #5d95f5);
    background: var(--form-attachment-hover-surface, #edf5ff);
    box-shadow: 0 0 0 4px var(--form-node-focus-ring, rgba(93, 149, 245, .14));
    transform: translateY(-1px);
}

.attachment-drop-zone.is-uploading {
    cursor: progress;
    background: linear-gradient(90deg, var(--form-attachment-surface), var(--form-attachment-hover-surface), var(--form-attachment-surface));
    background-size: 220% 100%;
    animation: attachment-drop-zone-loading 1.4s linear infinite;
}

.attachment-drop-zone.is-disabled {
    opacity: .55;
    cursor: not-allowed;
    pointer-events: none;
    filter: grayscale(.25);
}

.attachment-drop-zone__icon {
    display: inline-grid;
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    place-items: center;
    border: 1px solid var(--form-attachment-border, #c7daf5);
    border-radius: 10px;
    background: var(--form-attachment-icon-bg, #ffffff);
    color: var(--form-attachment-accent, #5d95f5);
    font-size: 19px;
    box-shadow: 0 3px 8px rgba(31, 42, 55, .06);
}

.attachment-drop-zone__content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 3px;
    padding: 0;
    color: var(--form-attachment-text, #3f4d66);
    line-height: 1.35;
    text-align: left;
}

.attachment-drop-zone__content strong {
    font-size: 13px;
    font-weight: 700;
}

.attachment-drop-zone__hint {
    display: block;
    color: var(--form-attachment-muted, #7c879d);
    font-size: 11px;
    font-weight: 500;
}

.attachment-drop-zone__drop-label {
    display: none;
}

.attachment-drop-zone.is-dragging .attachment-drop-zone__icon {
    color: var(--form-attachment-accent, #5d95f5);
    transform: translateY(-2px);
}

.attachment-drop-zone.is-dragging .attachment-drop-zone__content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.attachment-drop-zone.is-dragging .attachment-drop-zone__compact-label {
    display: none;
}

.attachment-drop-zone.is-dragging .attachment-drop-zone__drop-label,
.attachment-drop-zone.is-dragging .attachment-drop-zone__hint {
    display: block;
}

.attachment-drop-zone.is-dragging .attachment-drop-zone__drop-label {
    font-size: 14px;
}

.attachment-drop-zone.is-dragging .attachment-drop-zone__hint {
    font-size: 11px;
}

@keyframes attachment-drop-zone-loading {
    from { background-position: 100% 0; }
    to { background-position: -100% 0; }
}

@media (max-width: 640px) {
    .attachment-drop-zone {
        min-height: 82px;
        padding: 14px;
    }

    .attachment-drop-zone.is-dragging {
        min-height: 112px;
        flex-direction: column;
        text-align: center;
    }

    .attachment-drop-zone.is-dragging .attachment-drop-zone__content {
        align-items: center;
    }
}

