.statusTag {
    font-size: var(--management-font-body, 10px);
    padding: 3px 9px;
    border-radius: 999px;
    font-weight: 500;
    white-space: nowrap;
    display: inline-flex;
    align-items: center;
    line-height: 1;
    animation: slideInFromLeft 0.5s ease-out;
    width: 100%;
    justify-content: center;
}

    /* Pending / New */
    .statusTag.pending,
    .statusTag.new {
        background: var(--pending);
        color: #FFFFFF;
    }

    /* In Progress */

    .statusTag.in-progress {
        background: var(--theme-warning); /* màu cam */
        color: #ffffff; /* chữ trắng */
    }

    /* Accept / Approved / Client Accept */
    .statusTag.accepted,
    .statusTag.approved,
    .statusTag.approve,
    .statusTag.client-accept {
        background: var(--theme-success);
        color: #ffffff;
    }

    /* Reject / Decline / Client Refuse */
    .statusTag.rejected,
    .statusTag.declined,
    .statusTag.client-refuse {
        background: var(--theme-danger);
        color: #ffffff;
    }

    /* Done / Complete / Dispose / Archive */
    .statusTag.done,
    .statusTag.complete,
    .statusTag.dispose,
    .statusTag.archive {
        background: var(--both);
        color: #ffffff;
    }

    /* Unknown / ? */
    .statusTag.unknown {
        background: rgba(245,158,11,.18);
        color: #92400e;
    }



.statusTagInForm {
