/* wrapper cột phải */


.rightDock {
    position: fixed;
    top: calc(var(--management-header-height, 32px) + 8px);
    right: 12px;
    bottom: 70px;
    /*width: 420px;*/
    width: var(--rightdock-width);
    z-index: 1200;
    pointer-events: none;
    overflow: visible;
}

    .rightDock .dockCard {
        /*z-index: 1000;*/
        pointer-events: auto;
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        min-height: 0;
        background: #fff;
        border: 1px solid var(--border);
        border-radius: 14px;
        box-shadow: 0 14px 40px rgba(0, 0, 0, .18);
        padding: 12px 12px 10px;
        overflow: hidden;
        /* hiệu ứng trượt */
        opacity: 0;
        transform: translateX(36px) scale(.985);
        transition: transform .28s cubic-bezier(.2, .8, .2, 1), opacity .22s ease, visibility .22s ease;
        visibility: hidden;
        will-change: transform, opacity;
    }

    /* mở panel */
    .rightDock.is-open {
        pointer-events: auto;
    }

        .rightDock.is-open .dockCard {
            opacity: 1;
            transform: translateX(0) scale(1);
            visibility: visible;
        }

    /* đang đóng panel */
    .rightDock.is-closing {
        pointer-events: none;
    }

        .rightDock.is-closing .dockCard {
            opacity: 0;
            transform: translateX(42px) scale(.985);
            visibility: visible;
        }

