/* Sticky note icon */
.sticky-wrap {
    position: relative;
    width: 92px;
    height: 92px;
    flex: 0 0 92px;
    cursor: pointer;
    perspective: 700px;
    user-select: none;
}

    .sticky-wrap.hidden {
        display: none;
    }

.sticky-note {
    position: absolute;
    inset: 8px 0 0 4px;
    width: 78px;
    height: 78px;
    border-radius: 3px;
    background: linear-gradient(160deg,#f6d75c 0%, #f1d55f 48%, #f6d75c 100%);
    box-shadow: 0 18px 24px rgba(0,0,0,.16), 0 8px 8px rgba(0,0,0,.08), inset -12px -12px 20px rgba(255,255,255,.12), inset 10px 10px 18px rgba(255,255,255,.18);
    transform: rotate(-2deg) rotateX(10deg) rotateY(-8deg);
    transition: .22s ease;
    overflow: hidden;
}

    .sticky-note::before {
        content: "";
        position: absolute;
        inset: auto 0 0 0;
        height: 10px;
        background: linear-gradient(to bottom, rgba(0,0,0,0), rgba(0,0,0,.09));
        filter: blur(2px);
        opacity: .55;
    }

    .sticky-note::after {
        content: "";
        position: absolute;
        right: 0;
        bottom: 0;
        width: 16px;
        height: 16px;
        background: linear-gradient(135deg, #f1d55f 48%, #d4b843 48%, #fff6bb 100%);
        clip-path: polygon(100% 0,0 100%,100% 100%);
        box-shadow: -2px -2px 4px rgba(0,0,0,.08);
        opacity: .95;
    }

.pin {
    position: absolute;
    top: -9px;
    left: 50%;
    width: 15px;
    height: 15px;
    transform: translateX(-50%) rotate(-10deg);
    background: radial-gradient(circle at 35% 35%, #ff7f7f 0%, #dc2626 65%, #a70c0c 100%);
    border-radius: 50%;
    box-shadow: 0 2px 3px rgba(0, 0, 0, .22);
    z-index: 3;
}

    .pin::before {
        content: "";
        position: absolute;
        left: 3px;
        top: 13px;
        width: 2px;
        height: 9px;
        background: linear-gradient(to bottom, #d1d5db, #6b7280);
        transform: rotate(28deg);
        border-radius: 2px;
        box-shadow: 0 1px 1px rgba(0, 0, 0, .18);
    }

.sticky-badge {
    position: absolute;
    top: 12px;
    right: -8px;
    z-index: 4;
    background: #ef4444;
    color: #fff;
    min-width: 24px;
    height: 24px;
    padding: 0 7px;
    border-radius: 999px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 800;
    box-shadow: 0 6px 16px rgba(239,68,68,.35);
    border: 2px solid #fff;
}

.sticky-mini-text {
    position: absolute;
    left: 12px;
    top: 18px;
    right: 12px;
    z-index: 2;
    font-size: 10px;
    line-height: 1.4;
    color: #7a5d00;
    font-weight: 700;
    overflow: hidden;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    opacity: .92;
}

.sticky-wrap:hover .sticky-note {
    transform: rotate(0deg) rotateX(0deg) rotateY(0deg) translateY(-2px);
}

.sticky-wrap.wobble .sticky-note {
    animation: wobble 2.6s ease-in-out infinite;
    transform-origin: top center;
}

@keyframes wobble {
    0%,100% {
        transform: rotate(-2deg) rotateX(10deg) rotateY(-8deg)
    }

    25% {
        transform: rotate(1deg) rotateX(8deg) rotateY(6deg)
    }

    50% {
        transform: rotate(-1deg) rotateX(4deg) rotateY(-5deg)
    }

    75% {
        transform: rotate(2deg) rotateX(7deg) rotateY(4deg)
    }
}

