.triangle {
    width: 0;
    height: 0;
    border-left: 35px solid transparent;
    border-right: 35px solid transparent;
    border-bottom: 60px solid #ffffff;
    position: relative;
    margin-bottom: 10px;
}

    .triangle::after {
        content: "!";
        position: absolute;
        top: 18px;
        left: -5px;
        font-size: 28px;
