/* Triangle-mini (to hơn) */
.triangle-mini {
    width: 0;
    height: 0;
    border-left: 7px solid transparent;
    border-right: 7px solid transparent;
    border-bottom: 14px solid white;
    position: relative;
}

    /* Viền tam giác */
    .triangle-mini::before {
        content: "";
        position: absolute;
        top: -1.5px;
        left: -8.5px;
        border-left: 8.5px solid transparent;
        border-right: 8.5px solid transparent;
        border-bottom: 16px solid #f37021;
        z-index: -1;
    }

    /* Dấu ! (to & rõ hơn) */
    .triangle-mini::after {
        content: "!";
        position: absolute;
        top: 3px;
        left: -0.1rem;
        font-size: 9px;
        font-weight: bold;
        color: #f37021;
    }

/* Hover đổi màu */
.report-mini:hover .triangle-mini .triangle-mini::after {
    border-bottom-color: #ffffff;
}

