.signalr-monitor {
    position: relative;
    top: 7px;
    right: 60px;
    display: flex;
    align-items: center;
    gap: 4px;
    cursor: pointer;
}

.signalr-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: gray;
}

.signalr-connected .signalr-dot {
    background: #28a745;
}

.signalr-reconnecting .signalr-dot {
    background: #ff9800;
}

.signalr-disconnected .signalr-dot {
    background: #dc3545;
}



/* Connected: nhấp nháy nhẹ xanh -> xám -> xanh */
.signalr-connected.signalr-blink .signalr-dot {
    animation: pulseSignalR 0.2s infinite;
}

/* Reconnecting: nháy nhanh hơn (cam -> xám) */
.signalr-reconnecting.signalr-blink .signalr-dot {
    animation: pulseSignalR 1s infinite;
}

/* Disconnected: đỏ tĩnh */
.signalr-disconnected.signalr-blink .signalr-dot {
}


@keyframes blinkSignalR {
    0% {
        background: #28a745; /* xanh */
    }

    50% {
        background: gray; /* xám */
    }

    100% {
        background: #28a745; /* xanh */
    }
}

/* Animation reconnect (cảnh báo hơn) */
@keyframes blinkReconnect {
    0% {
        background: #ff9800;
    }

    50% {
        background: #ddd;
    }

    100% {
        background: #ff9800;
    }
}


@keyframes pulseSignalR {
    0% {
        opacity: 1;
    }

    50% {
        opacity: .3;
    }

    100% {
        opacity: 1;
    }
}

