    }

/* Keep long application menus inside the viewport. */
.main-sidebar > .sidebar {
    box-sizing: border-box;
    height: calc(100vh - var(--management-header-height, 32px)) !important;
    max-height: calc(100vh - var(--management-header-height, 32px));
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
}

/* Compact sidebar density. Keep the icon centered in the 45px collapsed rail
   while using the same vertical rhythm for expanded and nested menu items. */
.skin-re .sidebar-menu > li > a {
    min-height: 30px;
    padding: var(--management-menu-item-padding-y) var(--management-menu-item-padding-x) !important;
    line-height: 16px;
}

.skin-re .sidebar-menu > li > a > :is(.fa, .glyphicon, .ion) {
