}

.skin-re .sidebar-menu .treeview-menu {
    padding-top: 2px;
    padding-bottom: 2px;
}

.skin-re .sidebar-menu .treeview-menu > li > a {
    min-height: 26px;
    padding: var(--management-submenu-item-padding-y) 8px var(--management-submenu-item-padding-y) 20px !important;
    line-height: 16px;
}

@media (min-width: 768px) {
    .skin-re.sidebar-mini.sidebar-collapse .sidebar-menu > li > a {
        padding-right: var(--management-menu-item-padding-x) !important;
        padding-left: var(--management-menu-item-padding-x) !important;
    }
}

/* Neutralize the old inline height assigned to .tf-tree. */
.main-sidebar > .sidebar > .sidebar-menu.tree {
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
}

.main-sidebar > .sidebar::-webkit-scrollbar {
