}

/* Match pane spacing to the compact overview/header density. Inline form
   styles define these values repeatedly, so the shared tokens stay authoritative. */
.contentGrid {
    height: calc(100vh - var(--management-header-height, 32px));
    margin-right: var(--collapsed-form-mr);
    display: grid;
    grid-template-columns: minmax(260px, 420px) 10px minmax(620px, 1fr);
    gap: 0;
    box-sizing: border-box;
    min-height: 0;
    min-width: 0;
    padding: var(--form-pane-padding) !important;
}

.contentGrid > .pane-left {
    padding-right: var(--form-pane-side-padding) !important;
}

.contentGrid > .pane-right {
    padding-left: var(--form-pane-side-padding) !important;
}

