body.skin-re :is(.statusTag, .overview-status-pill, .decision-common-status) {
    font-size: var(--management-font-body) !important;
}

body.skin-re :is([id^="qt-overviewRoot_"], [id^="pi-overviewRoot_"])
    :is(.qt-cardHeader .h, .pi-cardHeader .h, .dept-header .dept-title,
