body.skin-re #rightCommentList
    :is(.dx-form-group-caption, .dx-toolbar-label, .dx-toolbar-label > div) {
    font-size: var(--management-font-title) !important;
}

body.skin-re #rightCommentList > :not(iframe),
body.skin-re #rightCommentList > [id^="form_"] {
    box-sizing: border-box;
    padding: 4px !important;
}

body.skin-re #rightCommentList .ct-item {
    padding: 6px 8px !important;
