}

body.skin-re #rightCommentList :is(td, th) {
    padding: 3px 5px !important;
}

body.skin-re #rightCommentList .dx-layout-manager .dx-field-item {
    padding-top: 3px !important;
    padding-right: 3px !important;
    padding-bottom: 3px !important;
    padding-left: 3px !important;
}

body.skin-re #rightCommentList .dx-form-group-with-caption > .dx-form-group-content {
