}

body.skin-re #rightCommentList .dx-button-content {
    min-height: 24px;
    padding: 3px 7px !important;
}

body.skin-re #rightCommentList .dx-datagrid :is(.dx-header-row, .dx-data-row) > td {
    padding: 4px 6px !important;
