/* Global proportional style adjustments for the entire application */

/* Global padding overrides for cards, panels, and dashboard containers */
.panel,
.chart-card,
.card,
.flow-sidebar-card,
.flow-form-card,
.flow-empty-state,
.menu-tools,
.menu-preview,
.menu-property,
.dg-toolbox,
.dg-center,
.dg-settings,
.toolbox,
.canvas,
.property,
.active-users-panel,
.evaluation-panel,
.database-card,
.sla-sidebar-card,
.sla-form-card,
.sql-form-card,
.sql-logs-card,
.notification-settings-card,
.notification-grid-card,
.tat-analytics-card,
.mail-designer-sidebar,
.mail-designer-canvas,
.mail-designer-property,
.kpi-mini-card,
.url-log-item,
.flow-palette-item,
.flow-toolbar,
.info-panel,
.user-management th,
.user-management td,
.user-management button,
.panel-header button {
  padding: 5px !important;
}

/* Form component input padding forced to 5px */
input,
select,
textarea,
.dx-texteditor-input,
.tmivcom-textbox input,
.tmivcom-numberbox input,
.tmivcom-selectbox-input,
.tmivcom-selectbox-input input,
.tmivcom-dropdownbox-input,
.tmivcom-dropdownbox-input input,
.flow-actions input,
.flow-form-card input,
.flow-form-card select,
.flow-form-card textarea,
.menu-property input,
.menu-property select,
.filter-input-wrap input,
.filter-input-wrap select,
.grid-cell input {
  padding: 5px !important;
  box-sizing: border-box;
}

/* Keep DataGrid search text clear of the search icon.
   This must follow the global input padding rule above. */
.dx-datagrid .dx-searchbox .dx-texteditor-input,
.dx-datagrid .dx-searchbox .dx-placeholder::before {
  padding-left: 34px !important;
}

.dx-rtl .dx-datagrid .dx-searchbox .dx-texteditor-input,
.dx-rtl .dx-datagrid .dx-searchbox .dx-placeholder::before,
.dx-datagrid .dx-searchbox.dx-rtl .dx-texteditor-input,
.dx-datagrid .dx-searchbox.dx-rtl .dx-placeholder::before {
  padding-right: 34px !important;
  padding-left: 5px !important;
}

/* Keep filter-row text clear of the filter-operation menu icon. */
.dx-datagrid-filter-row .dx-editor-cell .dx-editor-with-menu .dx-texteditor-input,
.dx-datagrid-filter-row .dx-editor-cell .dx-editor-with-menu .dx-placeholder::before {
  padding-left: 32px !important;
}

.dx-rtl .dx-datagrid-filter-row .dx-editor-cell .dx-editor-with-menu .dx-texteditor-input,
.dx-rtl .dx-datagrid-filter-row .dx-editor-cell .dx-editor-with-menu .dx-placeholder::before,
.dx-datagrid-filter-row.dx-rtl .dx-editor-cell .dx-editor-with-menu .dx-texteditor-input,
.dx-datagrid-filter-row.dx-rtl .dx-editor-cell .dx-editor-with-menu .dx-placeholder::before {
  padding-right: 32px !important;
  padding-left: 5px !important;
}

/* Global proportional font size reduction to 11px and 12px */
h1, h2, h3, h4, h5, h6,
.dx-form-group-caption,
.dx-field-item-label-text,
.brand,
.kpi-mini-val,
.user-management h2,
.panel-header h2 {
