}

body,
p,
span,
label,
input,
select,
textarea,
button,
table,
td,
th,
a,
li,
ul,
ol,
strong,
b,
small,
pre,
code,
.sidebar nav button,
.kpi-mini-label,
.dx-widget,
.dx-widget *,
.user-management td,
.user-management th,
.user-management button,
.panel-header button {
  font-size: 11px !important;
}

/* Theme-aware DevExtreme popup header. Keep this after the global dx-widget
   typography rule so popup titles retain their visual hierarchy. */
body.skin-re .dx-popup-wrapper > .dx-overlay-content {
  border-color: var(--theme-border, #dbe3ec);
  background: var(--theme-surface, #fff);
  color: var(--theme-text, #334155);
}

body.skin-re .dx-popup-wrapper > .dx-overlay-content > .dx-popup-title.dx-toolbar {
  min-height: 42px;
  padding: 5px 8px 5px 16px !important;
  border-bottom: 1px solid var(--theme-border, #dbe3ec);
  background: linear-gradient(
    90deg,
    var(--theme-primary-soft, #eff6ff) 0,
    var(--theme-surface, #fff) 72%
  );
  box-shadow: inset 3px 0 0 var(--theme-primary, #2563eb);
  color: var(--theme-text-strong, #0f172a);
  box-sizing: border-box;
}

body.skin-re .dx-popup-wrapper > .dx-overlay-content > .dx-popup-title
  .dx-toolbar-items-container {
  height: 32px;
  min-height: 32px;
}

body.skin-re .dx-popup-wrapper > .dx-overlay-content > .dx-popup-title
  :is(.dx-toolbar-label, .dx-toolbar-label > div) {
  color: var(--theme-text-strong, #0f172a);
  font-size: 13px !important;
  font-weight: 650;
  line-height: 1.35;
}

body.skin-re .dx-popup-wrapper > .dx-overlay-content > .dx-popup-title
  .dx-closebutton {
  width: 28px;
  min-width: 28px;
  height: 28px;
  margin: 0;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent !important;
  color: var(--theme-muted, #64748b);
}

body.skin-re .dx-popup-wrapper > .dx-overlay-content > .dx-popup-title
  .dx-closebutton .dx-icon {
  width: 26px;
  height: 26px;
  padding: 5px;
  color: inherit;
  font-size: 16px !important;
  line-height: 16px;
}

body.skin-re .dx-popup-wrapper > .dx-overlay-content > .dx-popup-title
  .dx-closebutton:hover {
  border-color: var(--theme-border-strong, #cbd5e1);
  background: var(--theme-primary-soft, #eff6ff) !important;
  color: var(--theme-primary, #2563eb);
}

body.skin-re .dx-popup-wrapper > .dx-overlay-content > .dx-popup-title
  .dx-closebutton:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--theme-primary-ring, rgba(37, 99, 235, .18));
}

body.skin-re .dx-rtl.dx-popup-wrapper > .dx-overlay-content > .dx-popup-title.dx-toolbar,
body.skin-re .dx-popup-wrapper.dx-rtl > .dx-overlay-content > .dx-popup-title.dx-toolbar {
  padding-right: 16px !important;
  padding-left: 8px !important;
  background: linear-gradient(
    270deg,
    var(--theme-primary-soft, #eff6ff) 0,
    var(--theme-surface, #fff) 72%
  );
  box-shadow: inset -3px 0 0 var(--theme-primary, #2563eb);
}

/* SweetAlert2 isolation: global typography rules above must not resize its
   em-based icons or collapse the dialog hierarchy. */
.swal2-container {
  z-index: 100000 !important;
  padding: 16px !important;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
}

.swal2-container.swal2-backdrop-show {
  background: rgba(15, 23, 42, .42) !important;
  backdrop-filter: blur(2px);
}

.swal2-container .swal2-popup:not(.swal2-toast) {
  width: min(420px, calc(100vw - 32px));
  max-width: 100%;
  padding: 24px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, .28);
  border-radius: 16px;
  background: var(--theme-surface, #fff);
  color: var(--theme-text, #0f172a);
  box-shadow: 0 24px 70px rgba(15, 23, 42, .24);
  font-size: 16px !important;
}

/* SweetAlert draws its icons with em-sized spans. Restore inheritance after
   the application's global `span { font-size: 11px !important; }` rule. */
.swal2-container .swal2-icon span,
.swal2-container .swal2-icon [class^="swal2-"] {
  font-size: inherit !important;
}

.swal2-container .swal2-icon {
  margin: 0 auto 14px;
}

.swal2-container .swal2-title,
.swal2-container .swal2-title * {
  margin: 0;
  padding: 0;
  color: var(--theme-text-strong, #0f172a);
  font-size: 18px !important;
  font-weight: 700 !important;
  line-height: 1.4;
  letter-spacing: -.01em;
}

.swal2-container .swal2-html-container,
.swal2-container .swal2-html-container * {
  color: var(--theme-muted, #64748b);
  font-size: 13px !important;
  line-height: 1.55;
}

.swal2-container .swal2-html-container {
  margin: 8px 0 0;
  padding: 0 8px;
}

.swal2-container .swal2-actions {
  gap: 8px;
  margin: 20px 0 0;
}

.swal2-container .swal2-styled {
  min-width: 88px;
  min-height: 38px;
  margin: 0;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 13px !important;
  font-weight: 650 !important;
  line-height: 1.2;
  box-shadow: none;
  transition: background-color .16s ease, border-color .16s ease,
    box-shadow .16s ease, transform .1s ease;
}

.swal2-container .swal2-styled.swal2-confirm {
  background: var(--theme-primary, #2563eb) !important;
  color: var(--theme-on-primary, #fff) !important;
}

.swal2-container .swal2-styled.swal2-confirm:hover {
  background: var(--theme-primary-hover, #1d4ed8) !important;
}

.swal2-container .swal2-styled.swal2-cancel {
  border: 1px solid var(--theme-border, #dbe3ec);
  background: var(--theme-surface-muted, #f8fafc) !important;
  color: var(--theme-text, #334155) !important;
}

.swal2-container .swal2-styled.swal2-cancel:hover {
  border-color: #cbd5e1;
  background: #eef2f7 !important;
}

.swal2-container .swal2-styled:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--theme-primary-ring, rgba(37, 99, 235, .18));
}

.swal2-container .swal2-styled:active {
  transform: translateY(1px);
}

.swal2-container :is(.swal2-input, .swal2-select, .swal2-textarea) {
  border: 1px solid var(--theme-border-strong, #cbd5e1);
  border-radius: 8px;
  color: var(--theme-text, #0f172a);
  font-size: 13px !important;
  box-shadow: none;
}

.swal2-container :is(.swal2-input, .swal2-select, .swal2-textarea):focus {
  border-color: var(--theme-primary, #2563eb);
  outline: none;
  box-shadow: 0 0 0 3px var(--theme-primary-ring, rgba(37, 99, 235, .18));
}

.swal2-container .swal2-close {
  color: #94a3b8;
  font-size: 32px !important;
}

.swal2-container .swal2-validation-message {
  border-radius: 8px;
  font-size: 12px !important;
}

@media (max-width: 480px) {
  .swal2-container {
    padding: 10px !important;
  }

  .swal2-container .swal2-popup:not(.swal2-toast) {
    width: calc(100vw - 20px);
    padding: 20px 16px;
  }

  .swal2-container .swal2-actions {
    width: 100%;
  }

  .swal2-container .swal2-styled {
    flex: 1 1 120px;
  }
}
